/**
 * Tám mươi mốt lá số lấy nguyên từ tuvi.vn — nguồn chân lý của dự án ở những chỗ tử vi có nhiều trường phái.
 *
 * Thu bằng cách POST form lập lá số của họ (`POST /la-so` với `dayOfDOB`, `monthOfDOB`,
 * `yearOfDOB`, `calendar`, `hourOfDOB`, `gender`). Query string trên URL lá số chỉ để trang trí —
 * id trong slug mới quyết định lá số nào được dựng, nên sửa URL không đổi được ngày sinh.
 *
 * Bộ này phủ đủ 10 can năm, 12 chi năm, 12 tháng âm, 12 giờ sinh, 5 cục và cả bốn tổ hợp
 * Dương Nam / Dương Nữ / Âm Nam / Âm Nữ. Hai lá số cuối thêm vào để chạm hai ô miếu vượng còn
 * trống của Hỏa Tinh và Linh Tinh, hai lá số nữa để tách ô cân lượng của ngày mùng năm và
 * ngày hai mươi lăm. Hai mươi bốn lá số cuối là bộ giữ riêng: dùng để kiểm luật lưu niên trên dữ
 * liệu chưa từng tham gia dò, không phải để dò.
 *
 * Năm xem ghi riêng cho từng lá số. tuvi.vn chỉ nhận `viewYear` khi lá số **chưa tồn tại**; POST lại
 * cùng ngày sinh sẽ trả về bản đã lưu kèm năm xem cũ. Nhờ vậy hai mươi lá số cuối lấy được ở các năm
 * xem trải từ 2001 tới 2061, tách được tuổi khỏi năm sinh cho các tầng phụ thuộc năm xem.
 */

export interface TuViVnSao {
  readonly name: string;
  /** Miếu vượng; `null` khi trang gốc không in bậc cho sao đó tại cung đó. */
  readonly rating: string | null;
}

export interface TuViVnCung {
  readonly chiIndex: number;
  readonly cungName: string;
  readonly chinhTinh: readonly string[];
  /** Miếu vượng của từng chính tinh, cùng thứ tự với `chinhTinh`; `null` khi trang gốc không in. */
  readonly ratings: readonly (string | null)[];
  readonly trangSinh: string;
  readonly daiVanLabel: string;
  readonly luuNienLabel: string;
  readonly phuTinh: readonly TuViVnSao[];
  /** Nhãn `Th.N` — cung tháng của năm xem. */
  readonly cungThang: number;
  readonly daiVanStartAge: number;
  readonly hasTuan: boolean;
  readonly hasTriet: boolean;
}

export interface TuViVnChart {
  readonly input: {
    readonly day: number;
    readonly month: number;
    readonly year: number;
    /** Giờ đồng hồ như form của họ nhận, chưa quy sang chi. */
    readonly hour: number;
    readonly gender: 'nam' | 'nu';
    /** Năm xem lúc lá số được dựng — quyết định nhãn đại vận, cung tháng và lưu niên. */
    readonly viewYear: number;
  };
  readonly expected: {
    readonly yearPillar: string;
    readonly chuMenh: string;
    readonly chuThan: string;
    readonly banMenh: string;
    readonly cuc: string;
    readonly amDuong: string;
    readonly canLuong: string;
    readonly cungs: readonly TuViVnCung[];
  };
}

